// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface BloodSourceOut {
  source_id: number;
  name: string;
  kind: "BloodCenter" | "HospitalBloodBank" | "OwnBloodCenter";
  licence_number: string;
  agreement_document_id: number | null;
  agreement_title: string | null;
  agreement_valid_until: string | null;
  address: string | null;
  phone: string | null;
  is_active: boolean;
  row_version: number;
}

/** A licensed blood center or hospital blood bank the hospital receives blood from (the Act s.2(e), 2(n)). */
export interface BloodSourceIn {
  name: string;
  kind: "BloodCenter" | "HospitalBloodBank" | "OwnBloodCenter";
  /** The source's PBTA licence number */
  licence_number: string;
  /** The MOU or contract in the compliance register (GET /facility/compliance-documents), if kept there; II B and II C hospitals without their own blood bank transfuse under such a contract */
  agreement_document_id?: number | null;
  address?: string | null;
  phone?: string | null;
}

export interface BloodSourcePatch {
  name?: string | null;
  licence_number?: string | null;
  agreement_document_id?: number | null;
  address?: string | null;
  phone?: string | null;
  is_active?: boolean | null;
  /** row_version you read; VERSION_CONFLICT if it changed */
  expected_version: number;
}

export interface ComplianceDocumentOut {
  document_id: number;
  kind: "Licence" | "Registration" | "Certificate" | "Plan" | "Law";
  category: "Hospital" | "Radiation" | "Building" | "Fire" | "Lift" | "Boiler" | "Power" | "BloodTransfusion" | "Food" | "Waste" | "Pharmacy" | "Laboratory" | "Water" | "Environment" | "Emergency" | "Equipment" | "Staff" | "Other";
  title: string;
  authority: string | null;
  reference_no: string | null;
  issued_on: string | null;
  valid_until: string | null;
  renewal_lead_days: number;
  /** The official who keeps it current (MSDS ROM 119 i) */
  responsible_user_id: number | null;
  responsible_name: string | null;
  asset_id: number | null;
  asset_tag: string | null;
  asset_name: string | null;
  department_id: number | null;
  department_name: string | null;
  renewal_applied_on: string | null;
  renewal_reference: string | null;
  has_scan: boolean;
  content_type: "application/pdf" | "image/jpeg" | "image/png" | null;
  size_bytes: number | null;
  note: string | null;
  status: "Current" | "Renewed" | "Withdrawn";
  replaces_id: number | null;
  renewed_by_id: number | null;
  withdrawn_reason: string | null;
  /** Null: shipped with Haspataal */
  created_by_name: string | null;
  created_at: string;
  row_version: number;
  /** Days to the expiry (negative: expired); null without one */
  days_left: number | null;
  /** Computed from the dates every day: DueForRenewal within renewal_lead_days of the expiry */
  state: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | "Renewed" | "Withdrawn";
}

export interface EstablishmentOut {
  /** Name it as expected_revision when applying a change */
  revision: number;
  /** Null until the first profile is recorded */
  profile: CurrentProfileOut | null;
  /** The capabilities whose new work may start now */
  active: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** The rules that follow the PHC category, never a service: show them on their screens instead of learning them from errors (audit H-7) */
  rules_in_force: RuleInForceOut[];
  capabilities: CapabilityOut[];
  /** What each service-bound workspace and screen shows now. Apply it after login and again on establishment.changed; never decide it from the profile's category */
  views: ViewsOut;
}

export interface CurrentProfileOut {
  code: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  label: string;
  establishment: "Clinic" | "Hospital";
  /** The PHC's band, in words */
  beds: string;
  /** The MSDS framework (GET /msds/indicators?category=) */
  framework: string;
  framework_edition: string;
  indicators: number;
  registration_number: string;
  effective_from: string;
  /** The beds the licence names; null when none was entered */
  licensed_beds: number | null;
  confirmed_at: string;
  confirmed_by_name: string;
}

export interface RuleInForceOut {
  code: string;
  description: string;
  /** Whether it applies to this establishment's current profile */
  applies: boolean;
  /** The PHC categories it applies to */
  profiles: string[];
  /** What the server answers when the rule is not met */
  error_code: string;
  operations: string[];
  /** The screens that should say it before the server refuses */
  screens: string[];
  /** Where it is enforced (for the backend team) */
  source: string;
}

export interface CapabilityOut {
  capability: "dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes";
  label: string;
  purpose: string;
  /** Available (never switched on), Preparing (set up, no new work), Active, Retiring (no new work, open work continues), Retired (records only) */
  state: "Available" | "Preparing" | "Active" | "Retiring" | "Retired";
  state_since: string;
  changed_by_name: string | null;
  requires: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** Never Active under the Clinic profile */
  hospital_only: boolean;
  /** False: not in this release; it cannot be switched on */
  implemented: boolean;
  /** What the database refuses while it is not Active */
  new_work: string | null;
  /** The operations that start its new work: hide them unless it is Active (the API refuses them anyway: CAPABILITY_INACTIVE). Every other operation, reads and the steps of started work included, stays */
  operations: GateOut[];
  /** Its open work, while Active or Retiring */
  outstanding: OutstandingOut[];
  /** The services declared to the PHC (GET /phc/services) that name it; a declaration is what the PHC is told, never proof the service runs */
  phc_declared: string[];
  /** Where the declaration and this service disagree: declared but not running, or running but not declared. Advice only */
  declaration_note: string | null;
}

export interface GateOut {
  /** METHOD /path: it starts new work of this service (OpenAPI x-capability-gates) */
  operation: string;
  /** Only the requests it names (hide or disable that choice, not the whole action); null: every request */
  when: string | null;
  /** True: work started before the service began retiring continues while it is Retiring (show it then too) */
  continues_while_retiring: boolean;
}

export interface OutstandingOut {
  /** admissions, inpatient_bills, emergency_visits, operations, recovery_stays, lab_tests, imaging_orders, critical_results, prescriptions_to_dispense, stock_on_hand, drug_recalls, sterile_packs, programme_enrolments, procedure_notes */
  kind: string;
  count: number;
  /** What it is, in words */
  label: string;
  /** How it ends: completed, transferred or settled (it is never stranded) */
  how: string;
  /** The operations that end it, as METHOD /path; all stay allowed while the service is Retiring */
  operations: string[];
}

export interface ViewsOut {
  /** The workspaces that exist for a service; any other is core */
  workspaces: WorkspaceViewOut[];
  /** The screens that exist for a service (or sit in such a workspace); any other screen is core and always full */
  screens: ScreenViewOut[];
}

export interface WorkspaceViewOut {
  /** A workspace that exists for these services (GET /meta/workspaces) */
  workspace: string;
  /** Any one of them gives it its view */
  services: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** full or open_work: in the launcher (open_work with the banner 'No new ... from now on'); records: in the launcher marked 'Records'; hidden: not in the launcher */
  view: "full" | "open_work" | "records" | "setup" | "hidden";
}

export interface ScreenViewOut {
  /** The screen catalogue's id (GET /meta/screens, the MCP server's get_screen) */
  screen_id: string;
  workspace: string;
  /** Any one of them gives it its view */
  services: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** Daily work, the setup a service needs before it is switched on, or its registers and statistics */
  role: "work" | "setup" | "records";
  /** full: show it; open_work: show it without new work of the service and with the banner; records: history, prints and corrections only; setup: only from Facility settings; hidden: in no menu */
  view: "full" | "open_work" | "records" | "setup" | "hidden";
}

/** The licensed blood sources — GET /api/v1/blood/sources (who may call: holders of blood.view). */
export function listSources(query?: { include_inactive?: boolean }): Promise<BloodSourceOut[]> {
  return api<BloodSourceOut[]>("GET", withQuery(`/blood/sources`, query), undefined);
}

/** Add a blood source — POST /api/v1/blood/sources (who may call: holders of blood.bank.manage). */
export function addSource(body: BloodSourceIn): Promise<BloodSourceOut> {
  return api<BloodSourceOut>("POST", `/blood/sources`, body, { idempotent: true });
}

/** Change a blood source or stop receiving from it — PATCH /api/v1/blood/sources/{source_id} (who may call: holders of blood.bank.manage). */
export function updateSource(source_id: number, body: BloodSourcePatch): Promise<BloodSourceOut> {
  return api<BloodSourceOut>("PATCH", `/blood/sources/${source_id}`, body);
}

/** The compliance register — GET /api/v1/facility/compliance-documents (who may call: holders of facility.view or facility.compliance.manage or blood.bank.manage). */
export function listDocumentsFacilityCompliance(query?: { kind?: "Licence" | "Registration" | "Certificate" | "Plan" | "Law" | null; category?: "Hospital" | "Radiation" | "Building" | "Fire" | "Lift" | "Boiler" | "Power" | "BloodTransfusion" | "Food" | "Waste" | "Pharmacy" | "Laboratory" | "Water" | "Environment" | "Emergency" | "Equipment" | "Staff" | "Other" | null; state?: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | null; responsible_user_id?: number | null; include_closed?: boolean }): Promise<ComplianceDocumentOut[]> {
  return api<ComplianceDocumentOut[]>("GET", withQuery(`/facility/compliance-documents`, query), undefined);
}

/** The establishment's profile and services, with the configuration revision — GET /api/v1/establishment (who may call: any logged-in user). */
export function getEstablishment(): Promise<EstablishmentOut> {
  return api<EstablishmentOut>("GET", `/establishment`, undefined);
}
